const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',orders:'<path d="M8 4h11v17H5V4h3m0-2h8v4H8zM9 11h6m-6 5h6"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',truck:'<path d="M2 5h12v12H2zM14 10h4l4 4v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M5 17h14l-2-4V9A5 5 0 0 0 7 9v4zM10 21h4"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',shirt:'<path d="m8 3-6 4 3 6 3-2v10h8V11l3 2 3-6-6-4c-1 4-7 4-8 0Z"/>',alert:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3h.01"/>',box:'<path d="m3 7 9-5 9 5v11l-9 4-9-4V7Zm0 0 9 5 9-5m-9 5v10M7 5l10 5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',location:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.orders}</svg>`;
let state;try{state=JSON.parse(localStorage.getItem('hilando-v1')||'null')||{repairs:[],activity:[]}}catch{state={repairs:[],activity:[]}}
state.repairs??=[];state.activity??=[];
if(RapicosturaBranches.migrate(state)){try{localStorage.setItem('hilando-v1',JSON.stringify(state))}catch{}}
let page='inicio';const main=document.getElementById('main'),dialog=document.getElementById('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),6500)}
function modal(title,body){document.getElementById('dialog-content').innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="close" aria-label="Cerrar" onclick="dialog.close()">×</button></div>${body}`;if(!dialog.open)dialog.showModal()}
function button(label,action,primary=false,ico=''){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${ico?icon(ico):''}${label}</button>`}
function save(message){if(message)state.activity.unshift({message,time:nowText(),at:Date.now(),who:currentPerson,scope:'work'});try{localStorage.setItem('hilando-v1',JSON.stringify(state))}catch{toast('El navegador no permite guardar cambios.')}render()}

function responsibleBranch(r){return r.responsibleBranch||r.branch||'Por confirmar'}
